class CameraFeeds:
    """Own the Picamera2 objects outside Tkinter and retain only newest frames."""

    def __init__(self):
        self.lock = threading.Lock()
        self.frames = {}
        self.states = {0: 'Starting…', 1: 'Starting…'}
        self.stop_event = threading.Event()
        self.thread = None
        self.restart()

    def restart(self):
        if self.thread and self.thread.is_alive():
            self.stop_event.set()
            return False
        self.stop_event = threading.Event()
        with self.lock:
            self.frames.clear()
            self.states = {0: 'Starting…', 1: 'Starting…'}
        self.thread = threading.Thread(target=self.run, daemon=True)
        self.thread.start()
        return True

    def snapshot(self, index):
        with self.lock:
            frame = self.frames.get(index)
            status = self.states.get(index, 'Not detected')
        if frame and time.monotonic() - frame[1] > 2.0:
            return None, 'No recent frames — retry cameras'
        return (frame[0] if frame else None), status

    def analysis_snapshot(self,index):
        # Return the image and its OWN timestamp under the same lock.
        with self.lock:
            stored=self.frames.get(index)
            status=self.states.get(index,'Not detected')
            return (stored[0],stored[1],status) if stored else (None,None,status)

    def receive(self, request, index):
        try:
            from PIL import Image
            # Picamera2 BGR888 yields RGB byte order; convert to grayscale for alignment.
            image = Image.fromarray(request.make_array('main').copy()).convert('L')
            with self.lock:
                self.frames[index] = (image, time.monotonic())
                self.states[index] = 'Live'
        except Exception as exc:
            with self.lock:
                self.frames.pop(index, None)
                self.states[index] = 'Frame error: ' + str(exc)

    def run(self):
        cameras = []
        try:
            from picamera2 import Picamera2
            info = Picamera2.global_camera_info()
            for index in range(2):
                if self.stop_event.is_set():
                    break
                if index >= len(info):
                    with self.lock:
                        self.states[index] = 'Camera not detected by Pi'
                    continue

                camera = None
                try:
                    camera_num = info[index].get('Num', index)
                    camera = Picamera2(camera_num)
                    config = camera.create_preview_configuration(
                        main={'size': (640, 480), 'format': 'BGR888'},
                        controls={'FrameRate': 15},
                        buffer_count=4,
                    )
                    camera.configure(config)
                    camera.post_callback = lambda request, n=index: self.receive(request, n)
                    camera.start()
                    cameras.append(camera)
                except Exception as exc:
                    with self.lock:
                        self.states[index] = 'Camera error: ' + str(exc)
                    if camera is not None:
                        try:
                            camera.close()
                        except Exception:
                            pass

            self.stop_event.wait()
        except ImportError:
            with self.lock:
                self.states = dict.fromkeys(
                    (0, 1),
                    'Install python3-picamera2 and python3-pil.imagetk'
                )
        except Exception as exc:
            with self.lock:
                self.states = dict.fromkeys((0, 1), 'Camera startup failed: ' + str(exc))
        finally:
            for camera in cameras:
                try:
                    camera.stop()
                    camera.close()
                except Exception:
                    pass
            with self.lock:
                self.frames.clear()


