class BatteryEstimate:
    """Display-only, generic 3S Li-ion voltage estimate; not a calibrated fuel gauge.

    PB120B1 label: 11.1 V / 12.8 Ah, 9–12.6 V output. Intermediate
    points are a heuristic, NOT a manufacturer discharge curve. Load, age,
    temperature and charging affect accuracy. Never used for hardware control.
    """
    CURVE = ((9.0, 0), (9.9, 5), (10.5, 10), (10.8, 20),
             (11.1, 35), (11.4, 50), (11.7, 65), (12.0, 80),
             (12.3, 90), (12.6, 100))

    def __init__(self):
        self.samples = deque(maxlen=30)
        self.last_stamp = None

    def reset(self):
        self.samples.clear()
        self.last_stamp = None

    def update(self, state, source, now):
        if source != 'Battery alone':
            self.reset()
            return None, 'External / charging'
        try:
            voltage = float(state.get('voltage', float('nan')))
            stamp = float(state.get('_status_monotonic', float('nan')))
            valid = (state.get('connected') and state.get('inaok') == 1
                     and math.isfinite(voltage) and math.isfinite(stamp)
                     and 0 <= now - stamp < 3 and 8.0 <= voltage <= 12.8)
        except (TypeError, ValueError):
            valid = False
        if not valid:
            self.reset()
            return None, 'No battery data'
        if self.samples and stamp - self.samples[-1][0] >= 3:
            self.reset()
        if stamp != self.last_stamp:
            self.samples.append((stamp, voltage))
            self.last_stamp = stamp
        recent = sorted(v for t, v in self.samples if 0 <= now - t <= 10)
        voltage = recent[len(recent) // 2]
        percent = 0.0 if voltage <= self.CURVE[0][0] else 100.0
        for (lo, a), (hi, b) in zip(self.CURVE, self.CURVE[1:]):
            if lo <= voltage <= hi:
                percent = a + (b - a) * (voltage - lo) / (hi - lo)
                break
        # Five-percent increments avoid suggesting precision the sensor cannot give.
        percent = int(5 * round(percent / 5))
        return percent, ('Low' if percent <= 20 else 'Estimated')


class ESP32Link:
    """Verified, reconnecting USB link to the LOTUS ESP32-S3 controller."""

    def __init__(self, baud=115200):
        self.baud = baud
        self.lock = threading.Lock()
        self.tx_lock = threading.Lock()
        self.rx_condition = threading.Condition()
        self.rx_seq = 0
        self.rx_lines = deque(maxlen=100)
        self.serial_obj = None
        self.stop_event = threading.Event()
        self.last_valid_rx = 0.0
        self.state = {
            'connected': False,
            'port': None,
            'error': '',
            'last_event': '',
            'firmware': '',
            'pcb': float('nan'),
            'ambient': float('nan'),
            'humidity': float('nan'),
            'voltage': float('nan'),
            'current': float('nan'),
            'power': float('nan'),
            'tmpok': 0,
            'shtok': 0,
            'inaok': 0,
            'fanrpm': 0,
            'fanpct': 0,
            'fanauto': 1,
            'light': 0,
            'uv': 0,
            'uvactive': 0,
            'moving': 0,
            'xfault': 0,
            'yfault': 0,
            'zfault': 0,
            'xpos': 0,
            'ypos': 0,
            'zpos': 0,
        }
        self.thread = threading.Thread(target=self.run, daemon=True)
        self.thread.start()

    def snapshot(self):
        with self.lock:
            return dict(self.state)

    def _set(self, **kwargs):
        with self.lock:
            self.state.update(kwargs)

    def _candidate_ports(self):
        ports = []
        forced = os.environ.get('LOTUS_PORT', '').strip()
        if forced:
            ports.append(forced)
        ports.extend(sorted(glob.glob('/dev/ttyACM*')))
        ports.extend(sorted(glob.glob('/dev/ttyUSB*')))
        # Preserve order, remove duplicates.
        return list(dict.fromkeys(ports))

    @staticmethod
    def _open_serial(serial_module, port, baud):
        ser = serial_module.Serial(
            port=None,
            baudrate=baud,
            timeout=0.25,
            write_timeout=0.5,
        )
        # Avoid unwanted auto-reset behavior on adapters that expose DTR/RTS.
        ser.dtr = False
        ser.rts = False
        ser.port = port
        ser.open()
        return ser

    @staticmethod
    def _raw_write(ser, command):
        ser.write((command.strip() + '\n').encode('ascii', errors='ignore'))
        ser.flush()

    def _record_rx(self, line):
        with self.rx_condition:
            self.rx_seq += 1
            self.rx_lines.append((self.rx_seq, line))
            self.rx_condition.notify_all()

    def _parse_status(self, line):
        updates = {}
        for token in line.split()[1:]:
            if '=' not in token:
                continue
            key, value = token.split('=', 1)
            try:
                if key in ('pcb', 'ambient', 'humidity', 'voltage', 'current', 'power', 'light', 'uv'):
                    updates[key] = float(value)
                else:
                    updates[key] = int(value)
            except ValueError:
                pass
        if updates:
            updates['_status_monotonic'] = time.monotonic()
            updates['connected'] = True
            updates['error'] = ''
            self._set(**updates)
            return True
        return False

    def _parse_line(self, line):
        if not line:
            return False

        recognized = False
        if line.startswith('STATUS '):
            recognized = self._parse_status(line)
        elif line == 'PONG':
            self._set(connected=True, error='')
            recognized = True
        elif line.startswith('HELLO LOTUS_ESP32_S3 '):
            self._set(firmware=line.rsplit(' ', 1)[-1], connected=True, error='')
            recognized = True
        elif line.startswith('VERSION LOTUS_ESP32_S3 '):
            self._set(firmware=line.rsplit(' ', 1)[-1], last_event=line,
                      connected=True, error='')
            recognized = True
        elif line.startswith('READY '):
            self._set(last_event=line, connected=True, error='')
            recognized = True
        elif line.startswith('EVENT '):
            self._set(last_event=line, connected=True, error='')
            recognized = True
        elif line.startswith('ERR '):
            self._set(last_event=line, error=line, connected=True)
            recognized = True
        elif line.startswith('OK ') or line.startswith('HELP '):
            self._set(last_event=line, connected=True)
            recognized = True

        if recognized:
            self.last_valid_rx = time.monotonic()
            self._record_rx(line)
        return recognized

    def _probe(self, serial_module, port):
        ser = None
        try:
            ser = self._open_serial(serial_module, port, self.baud)
            time.sleep(0.25)
            try:
                ser.reset_input_buffer()
            except Exception:
                pass

            # Require BOTH PONG and a LOTUS firmware signature so another
            # serial device cannot be mistaken for the controller.
            self._raw_write(ser, 'PING')
            pong = False
            deadline = time.monotonic() + 1.2
            while time.monotonic() < deadline:
                raw = ser.readline()
                if not raw:
                    continue
                line = raw.decode('utf-8', errors='ignore').strip()
                if line == 'PONG':
                    pong = True
                    break
                self._parse_line(line)
            if not pong:
                raise RuntimeError('no PONG')

            self._raw_write(ser, 'VERSION')
            signature = False
            deadline = time.monotonic() + 1.2
            while time.monotonic() < deadline:
                raw = ser.readline()
                if not raw:
                    continue
                line = raw.decode('utf-8', errors='ignore').strip()
                self._parse_line(line)
                if line.startswith('VERSION LOTUS_ESP32_S3 '):
                    signature = True
                    break
            if not signature:
                raise RuntimeError('LOTUS firmware signature not found')
            return ser
        except Exception:
            if ser is not None:
                try:
                    ser.close()
                except Exception:
                    pass
            return None

    def send(self, command):
        with self.lock:
            ser = self.serial_obj
            connected = self.state.get('connected', False)
        if ser is None or not getattr(ser, 'is_open', False) or not connected:
            return False
        try:
            with self.tx_lock:
                self._raw_write(ser, command)
            return True
        except Exception as exc:
            self._set(connected=False, error=str(exc))
            return False

    def request(self, command, expect_prefix, timeout=1.0):
        """Send a command and wait briefly for its matching OK/ERR response."""
        with self.rx_condition:
            start_seq = self.rx_seq
        if not self.send(command):
            return False, 'ESP32 offline'

        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            with self.rx_condition:
                for seq, line in list(self.rx_lines):
                    if seq <= start_seq:
                        continue
                    if line.startswith('ERR '):
                        return False, line
                    if line.startswith(expect_prefix):
                        return True, line
                remaining = deadline - time.monotonic()
                if remaining > 0:
                    self.rx_condition.wait(min(remaining, 0.1))
        return False, 'Timed out waiting for ESP32 response'

    def run(self):
        try:
            import serial
        except ImportError:
            self._set(error='Install python3-serial', connected=False)
            return

        while not self.stop_event.is_set():
            ports = self._candidate_ports()
            if not ports:
                self._set(connected=False, port=None,
                          error='ESP32 USB serial not found')
                self.stop_event.wait(1.0)
                continue

            ser = None
            selected_port = None
            for port in ports:
                if self.stop_event.is_set():
                    break
                self._set(connected=False, port=port,
                          error='Checking LOTUS controller…')
                ser = self._probe(serial, port)
                if ser is not None:
                    selected_port = port
                    break

            if ser is None:
                self._set(connected=False, port=None,
                          error='No LOTUS ESP32-S3 answered PING/VERSION')
                self.stop_event.wait(1.0)
                continue

            try:
                with self.lock:
                    self.serial_obj = ser
                    self.state.update({
                        'connected': True,
                        'port': selected_port,
                        'error': '',
                    })
                self.last_valid_rx = time.monotonic()
                self.send('STATUS')
                next_status = time.monotonic() + 0.75

                while not self.stop_event.is_set():
                    now = time.monotonic()
                    if now >= next_status:
                        if not self.send('STATUS'):
                            raise RuntimeError('serial write failed')
                        next_status = now + 0.75

                    raw = ser.readline()
                    if raw:
                        line = raw.decode('utf-8', errors='ignore').strip()
                        self._parse_line(line)

                    # A cable can disappear without readline immediately raising.
                    if time.monotonic() - self.last_valid_rx > 4.0:
                        raise RuntimeError('ESP32 stopped responding')

            except Exception as exc:
                self._set(connected=False, error=str(exc))
            finally:
                with self.lock:
                    if self.serial_obj is ser:
                        self.serial_obj = None
                if ser is not None:
                    try:
                        ser.close()
                    except Exception:
                        pass
            self.stop_event.wait(0.75)

    def close(self):
        self.stop_event.set()
        with self.lock:
            ser = self.serial_obj
        if ser is not None:
            try:
                ser.close()
            except Exception:
                pass


