    def home_tile(self, parent, icon, name, description, callback, primary):
        # Single Canvas surface prevents ugly rectangles around text on hover.
        normal = PURPLE2 if primary else WHITE
        hover = PURPLE if primary else PLIGHT
        pressed = '#5B21B6' if primary else '#DDD6FE'
        tile = tk.Canvas(parent, bg=normal, width=1, height=1, bd=0,
                         highlightthickness=0, takefocus=True, cursor='hand2')
        tile.pack(fill='both', expand=True, padx=1, pady=1)
        state = {'inside': False, 'pressed': False, 'focused': False}
        icon_id = tile.create_text(0, 0, text=icon, font=(FONT, 25, 'bold'),
                                   fill='white' if primary else PURPLE2)
        title_id = tile.create_text(0, 0, text=name, anchor='w',
                                    font=(FONT, 13, 'bold'), fill='white' if primary else TEXT)
        desc_id = tile.create_text(0, 0, text=description, anchor='w',
                                   font=(FONT, 8), fill='#E8DEFF' if primary else MUTED)
        focus_id = tile.create_rectangle(0, 0, 0, 0, outline='', width=2)

        def paint():
            tile.config(bg=pressed if state['pressed'] and state['inside'] else
                        hover if state['inside'] else normal)
            tile.itemconfig(focus_id, outline=('white' if primary else PURPLE)
                            if state['focused'] else '')

        def resize(event):
            width, height = event.width, event.height
            tile.coords(icon_id, .12 * width, .5 * height)
            tile.coords(title_id, .27 * width, .42 * height)
            tile.coords(desc_id, .27 * width, .62 * height)
            tile.coords(focus_id, 4, 4, width - 4, height - 4)

        tile.bind('<Configure>', resize)
        tile.bind('<Enter>', lambda e: (state.__setitem__('inside', True), paint()))
        tile.bind('<Leave>', lambda e: (state.__setitem__('inside', False), paint()))

        def press(event):
            tile.focus_set()
            state['pressed'] = True
            paint()

        def release(event):
            activate = (state['pressed'] and 0 <= event.x < tile.winfo_width()
                        and 0 <= event.y < tile.winfo_height())
            state['pressed'] = False
            paint()
            if activate:
                callback()

        tile.bind('<ButtonPress-1>', press)
        tile.bind('<ButtonRelease-1>', release)
        tile.bind('<FocusIn>', lambda e: (state.__setitem__('focused', True), paint()))
        tile.bind('<FocusOut>', lambda e: (state.__setitem__('focused', False), paint()))
        tile.bind('<Return>', lambda e: callback())
        tile.bind('<space>', lambda e: callback())

