    def camera_box(self, parent, name):
        outer, box = self.bordered(parent, WHITE, PBORDER)
        head = tk.Frame(box, bg=WHITE, height=34)
        head.pack(fill='x')
        head.pack_propagate(False)
        tk.Label(head, text=name, bg=WHITE, fg=PURPLE,
                 font=(FONT, 10, 'bold')).pack(side='left', padx=10)
        tk.Button(head, text='Load Sample', command=lambda: self.load_sample(name),
                  bg=WHITE, fg=PURPLE, relief='flat', font=(FONT, 8)).pack(side='right', padx=8)
        tk.Button(head, text='Live / Retry', command=lambda: self.resume_camera(name),
                  bg=WHITE, fg=PURPLE, relief='flat', font=(FONT, 8)).pack(side='right')
        screen = tk.Canvas(box, bg=BLACK, highlightthickness=0, width=1, height=1)
        screen.pack(fill='both', expand=True, padx=7, pady=(0, 7))
        screen.image_id = screen.create_image(0, 0)
        screen.status_id = screen.create_text(0, 0, fill='white', font=(FONT, 8, 'bold'))
        self.camera_views[name] = screen
        return outer

    def update_camera_views(self):
        if self.closing:
            return
        for name, screen in list(self.camera_views.items()):
            width = max(1, screen.winfo_width())
            height = max(1, screen.winfo_height())
            sample = self.camera_images.get(name)
            frame, status = self.feeds.snapshot(self.camera_order[name])
            if sample is not None:
                factor = max(1, math.ceil(sample.width() / width),
                             math.ceil(sample.height() / max(1, height - 25)))
                screen.preview = sample.subsample(factor)
                status = 'LOADED SAMPLE • not live'
            elif frame is not None:
                from PIL import Image, ImageTk
                preview = orient_camera_frame(frame, name)
                preview.thumbnail((width, max(1, height - 25)), Image.Resampling.BILINEAR)
                screen.preview = ImageTk.PhotoImage(preview, master=self)
                status = f'LIVE • camera {self.camera_order[name]}'
            else:
                screen.preview = None
            screen.coords(screen.image_id, width / 2, height / 2 + 10)
            screen.itemconfig(screen.image_id,
                              image=screen.preview if screen.preview is not None else '')
            screen.coords(screen.status_id, width / 2,
                          12 if screen.preview is not None else height / 2)
            screen.itemconfig(screen.status_id, text=status, width=max(1, width - 16))
        self.after(80, self.update_camera_views)

    def load_sample(self, name):
        path = filedialog.askopenfilename(
            parent=self,
            title='Load sample for ' + name,
            filetypes=[('PNG images', '*.png'), ('GIF images', '*.gif')],
        )
        if not path:
            return
        try:
            self.camera_images[name] = tk.PhotoImage(file=path)
        except tk.TclError as exc:
            messagebox.showerror('Image could not be loaded', str(exc), parent=self)
            return
        self.show_live()

    def resume_camera(self, name):
        self.camera_images.pop(name, None)
        frame, _ = self.feeds.snapshot(self.camera_order[name])
        if frame is None and not self.retry_pending:
            self.retry_pending = True
            self.feeds.stop_event.set()
            self.retry_cameras()

    def retry_cameras(self):
        if self.closing:
            return
        if self.feeds.thread and self.feeds.thread.is_alive():
            self.after(100, self.retry_cameras)
        else:
            self.feeds.restart()
            self.retry_pending = False

    def swap_cameras(self):
        self.camera_order['X VIEW'], self.camera_order['Y VIEW'] = (
            self.camera_order['Y VIEW'], self.camera_order['X VIEW'])
        self.camera_images.clear()

    def capture_image(self, name, notify=True):
        image = self.camera_images.get(name)
        frame, status = self.feeds.snapshot(self.camera_order[name])
        if image is None and frame is None:
            messagebox.showinfo(
                'No image available',
                status + '\nCheck rpicam-hello --list-cameras, or load a sample.',
                parent=self,
            )
            return
        try:
            self.data_dir.mkdir(parents=True, exist_ok=True)
            path = self.data_dir / (
                name[0] + '_' + datetime.now().strftime('%Y%m%d_%H%M%S_%f') + '.png')
            if image is not None:
                image.write(str(path), format='png')
            else:
                orient_camera_frame(frame, name).save(path, format='PNG')
            if notify:
                messagebox.showinfo('Saved', f'Capture saved:\n{path}', parent=self)
            return path
        except (OSError, tk.TclError) as exc:
            messagebox.showerror('Save failed', str(exc), parent=self)
            return None

    def save_images(self):
        saved = 0
        for name in ('X VIEW', 'Y VIEW'):
            image = self.camera_images.get(name)
            frame, _ = self.feeds.snapshot(self.camera_order[name])
            if image is None and frame is None:
                continue
            if self.capture_image(name, notify=False) is not None:
                saved += 1
        messagebox.showinfo('Save Images',
                            f'Saved {saved} camera image(s) in\n{self.data_dir}',
                            parent=self)

    def open_captures(self):
        try:
            self.data_dir.mkdir(parents=True, exist_ok=True)
            subprocess.Popen(['xdg-open', str(self.data_dir)],
                             stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL)
        except (OSError, ValueError) as exc:
            messagebox.showerror('Open captures folder', str(exc), parent=self)

