    def motor_profile(self, axis='X'):
        # Defaults: Fine=1, Medium=50, Coarse=500 for all axes.
        # Pulse counts, NOT distances: stage displacement depends on gearing.
        profile = self.preferences.get('Default step', 'Fine')
        if profile == 'Coarse':
            return coarse_motor_profile(axis)
        if profile == 'Medium':
            return 50, 500
        return 1, 200

    def jog_button(self, parent, text, axis, direction, width=4, font_size=11):
        """Tap sends one motion; press-and-hold repeats bounded motion.

        On releasing a repeating jog, STOP flushes the controller queue.
        This is software-only stopping, not a hardware emergency circuit.
        """
        button = tk.Button(parent, text=text, bg=PLIGHT, fg=PURPLE,
                           activebackground=PBORDER, relief='flat',
                           font=(FONT, font_size, 'bold'), width=width, pady=4)
        button.bind('<ButtonPress-1>',
                    lambda e, a=axis, d=direction: self.begin_jog(a, d))
        button.bind('<ButtonRelease-1>', lambda e: self.end_jog())
        button.bind('<Leave>', lambda e: self.end_jog())
        return button

    def begin_jog(self, axis, direction):
        if self.jog_active is not None:
            self.end_jog()
        if not self.hw.snapshot().get('connected'):
            self.hardware_unavailable()
            return
        self.jog_active = (axis, direction)
        self.jog_started = time.monotonic()
        self.jog_repeated = False
        self.jog_last_sent = 0.0
        self.jog_once(axis, direction)
        self.jog_after = self.after(430, self.repeat_jog)

    def jog_once(self, axis, direction):
        pulses, pps = self.motor_profile(axis)
        if self.move_axis(axis, direction, popup_on_fail=False):
            # Avoid serial flood/firmware queue buildup on held buttons.
            self.jog_last_sent = time.monotonic() + pulses / pps + 0.12
            return True
        return False

    def repeat_jog(self):
        self.jog_after = None
        if self.closing or self.jog_active is None:
            return
        axis, direction = self.jog_active
        if not self.hw.snapshot().get('connected'):
            self.end_jog()
            return
        if time.monotonic() >= self.jog_last_sent:
            if self.jog_once(axis, direction):
                self.jog_repeated = True
        self.jog_after = self.after(110, self.repeat_jog)

    def end_jog(self):
        if self.jog_after is not None:
            try:
                self.after_cancel(self.jog_after)
            except tk.TclError:
                pass
            self.jog_after = None
        was_repeated = self.jog_repeated
        self.jog_active = None
        self.jog_repeated = False
        self.jog_started = None
        if was_repeated:
            # Stop remaining queued motion when the operator releases a hold.
            self.hw.send('STOP')
            self.log_hardware_event('TX STOP (jog released)')

    def move_axis(self, axis, direction, popup_on_fail=True):
        state = self.hw.snapshot()
        if not state.get('connected'):
            if popup_on_fail:
                self.hardware_unavailable()
            return False
        if state.get('uvactive') or self.cure_end is not None:
            if popup_on_fail:
                messagebox.showwarning('UV Cure Active',
                                       'Stop UV curing before moving the stage.',
                                       parent=self)
            return False
        if state.get(axis.lower() + 'fault'):
            if popup_on_fail:
                messagebox.showwarning('Motor Fault',
                                       f'{axis} driver fault is active.', parent=self)
            return False
        pulses, pps = self.motor_profile(axis)
        return self.send_hw(f'MOVE {axis} {int(direction) * pulses} {pps}',
                            popup_on_fail=popup_on_fail)

    def disable_motors(self):
        self.send_hw('ENABLE ALL 0')

    def zero_positions(self):
        ok, response = self.hw.request('ZERO ALL', 'OK ZERO', timeout=1.0)
        if ok:
            self.log_hardware_event('TX ZERO ALL')
            messagebox.showinfo(
                'Position',
                'Current X/Y/Z positions were set to zero in software.\n'
                'This does not physically home the stages.',
                parent=self,
            )
        else:
            messagebox.showwarning('Zero failed', response, parent=self)

    def emergency_stop(self):
        self.end_jog()
        # STOP already shuts UV off in firmware. UV_STOP is sent too for an
        # explicit second command in case STOP is ever changed later.
        self.hw.send('STOP')
        self.hw.send('UV_STOP')
        self.cure_end = None
        if self.cure_label is not None and self.cure_label.winfo_exists():
            self.cure_label.config(text='STOPPED')
        self.cure_message = 'Stop requested'
        self.log_hardware_event('EMERGENCY STOP')

    def auto_align_unavailable(self):
        messagebox.showinfo(
            'Auto Align',
            'Motor control is connected, but automatic alignment still needs the '
            'camera measurement algorithm to calculate live X/Y/Z corrections.',
            parent=self,
        )

