        main=self.page_shell('fan','Fan Control','IO21 PWM at 25 kHz • IO40 tachometer • 2 pulses/revolution')
        self.fan_controls=[]
        self.fan_status_label=tk.Label(main,text='',bg=WHITE,fg=PURPLE,
                                      font=(FONT,13,'bold'),justify='left',padx=15,pady=12)
