    def load_demo(self):
        from PIL import Image,ImageDraw
        for name in ('X VIEW','Y VIEW'):
            image=Image.new('RGB',(640,480),'white')
            draw=ImageDraw.Draw(image)
            draw.rectangle((30,180,284,220),fill='black')
            draw.rectangle((335,188,610,228),fill='black')
            self.analysis_samples[name]=image
            self.rois.pop(name,None)
        self.invalidate_analysis()

    def reset_scale(self,name):
        self.calibrations.pop(self.source_key(name),None)
        self.save_calibrations()
        self.invalidate_analysis()

    def load_analysis(self,name):
        self.auto_xy_stop('Auto XYZ paused for operator input')
        path=filedialog.askopenfilename(parent=self,title='Choose fiber image',
             filetypes=[('Images','*.png *.jpg *.jpeg *.bmp *.tif *.tiff'),('All files','*')])
        if not path:return
        try:
            from PIL import Image
            with Image.open(path) as image:
                self.analysis_samples[name]=image.convert('RGB')
            self.rois.pop(name,None)
            self.invalidate_analysis()
        except Exception as exc:
            messagebox.showerror('Image',str(exc),parent=self)

    def analysis_live(self,name):
        self.analysis_samples.pop(name,None)
        self.rois.pop(name,None)
        self.invalidate_analysis()

    def invalidate_analysis(self):
        self.auto_xy_stop('Auto XYZ stopped: image/settings changed')
        self.generation+=1
        self.measurements.clear()
        self.measurement_sources.clear()
        self.analysis_masks.clear()

    def pick_points(self,name,mode):
        self.auto_xy_stop('Auto XYZ paused for operator input')
        from PIL import Image,ImageTk
        image,source,stamp=self.source(name)
        if image is None:
            messagebox.showinfo('Image required','Load a sample or connect a camera first.',parent=self);return
        self.end_jog()
        top=tk.Toplevel(self);top.title('Select two points - '+name)
        tk.Label(top,text=('Click both ends of a known length, then enter its length in micrometers.' if mode=='scale' else
                           'Click two opposite corners around both fibers, their gap, and background.')).pack(padx=8,pady=8)
        display=image.copy();display.thumbnail((850,500),Image.Resampling.LANCZOS)
        canvas=tk.Canvas(top,width=display.width,height=display.height,bg=BLACK)
        canvas.pack(padx=8,pady=8)
        canvas.photo=ImageTk.PhotoImage(display,master=self)
        canvas.create_image(0,0,anchor='nw',image=canvas.photo)
        points=[]
        def click(event):
            points.append((event.x*image.width/display.width,event.y*image.height/display.height))
            canvas.create_oval(event.x-3,event.y-3,event.x+3,event.y+3,fill='cyan')
            if len(points)<2:return
            canvas.unbind('<Button-1>')
            if mode=='roi':
                (ax,ay),(bx,by)=points
                self.rois[name]=[min(ax,bx),min(ay,by),max(ax,bx),max(ay,by)]
            else:
                length=simpledialog.askfloat('Reference length','Known length (µm):',minvalue=.001,parent=top)
                distance=math.dist(*points)
                if length is None:top.destroy();return
                if distance<10:
                    messagebox.showerror('Calibration','Select a reference spanning at least 10 pixels.',parent=top)
                    top.destroy();return
                self.calibrations[self.source_key(name)]={'um_per_px':length/distance,
                    'reference_um':length,'reference_px':distance,'points':points,
                    'image_size':list(image.size),'timestamp':datetime.now().isoformat(),
                    'assumption':'Square pixels / isotropic scale; operator reference, not accuracy validation.'}
                if not self.save_calibrations():top.destroy();return
            self.invalidate_analysis();top.destroy()
        canvas.bind('<Button-1>',click)
        if mode=='roi':
            tk.Button(top,text='Use full image',command=lambda:(self.rois.pop(name,None),self.invalidate_analysis(),top.destroy())).pack(pady=4)

    def save_calibrations(self):
        try:
            self.data_dir.mkdir(parents=True,exist_ok=True)
            path=self.data_dir/'engineering_calibration.json'
            tmp=path.with_suffix('.tmp')
            tmp.write_text(json.dumps({'cameras':self.calibrations,'motors':self.motor_calibrations},indent=2))
            tmp.replace(path)
            return True
        except OSError as exc:
            messagebox.showerror('Could not save calibration',str(exc),parent=self)
            return False

    def overlay(self,image,result):
        from PIL import ImageDraw
        image=image.copy().convert('RGB');draw=ImageDraw.Draw(image)
        if result.get('roi'):draw.rectangle(result['roi'],outline='yellow',width=1)
        if result.get('valid'):
            for line in result['lines']:
                a,b=line['x0'],line['x1'];m,c=line['m'],line['b'];d=line['diameter_px']/2
                draw.line((a,m*a+c,b,m*b+c),fill='cyan',width=2)
                for edge in (-d,d):draw.line((a,m*a+c+edge,b,m*b+c+edge),fill='lime',width=1)
                end=b if line==result['lines'][0] else a
                draw.line((end,m*end+c-d,end,m*end+c+d),fill='magenta',width=2)
            for tip in result.get('tip_profiles',[]):
                for x,y in tip['profile']:draw.ellipse((x-1,y-1,x+1,y+1),fill='orange')
            for cleave in result.get('cleaves',{}).values():
                if cleave.get('valid'):
                    draw.line([tuple(p) for p in cleave['ideal_line']],fill='dodgerblue',width=1)
                    draw.line([tuple(p) for p in cleave['fitted_line']],fill='white',width=1)
        return image

    def refresh_alignment_metrics(self):
        if not self.alignment_page_active:return
        now=time.monotonic()
        for name in ('X VIEW','Y VIEW'):
            r=self.measurements.get(name,{})
            valid=r.get('valid') and r.get('source')=='live' and now-(r.get('source_stamp') or 0)<=2
            cal=r.get('calibration_at_measurement') if valid else None
            scale=cal['um_per_px'] if cal else 1
            unit='µm' if cal else 'px'
            for key in ('gap_px','offset_px','angle_deg'):
                widget=self.alignment_metrics.get((name,key))
                if widget is None or not widget.winfo_exists():continue
                value=r.get(key)
                text=(f'{value*scale:+.2f} {unit}' if key=='offset_px' else f'{value*scale:.2f} {unit}') if valid and finite_value(value) else '—'
                if key=='angle_deg':text=f'{value:+.2f}°' if valid and finite_value(value) else '—'
                widget.config(text=text)
        if self.alignment_live_status is not None and self.alignment_live_status.winfo_exists():
            status=fiber_alignment_status(self.measurements,self.alignment_criteria)
            self.alignment_live_status.config(text=status['label']+' — '+status['detail'])

    def render_engineering(self):
        from PIL import Image,ImageTk
        status=fiber_alignment_status(self.measurements,self.alignment_criteria)
        banner=self.alignment_status_label
        if banner is not None and banner.winfo_exists():
            color=RED if status['label']=='Misaligned' else (GREEN if status['label'].startswith(('Aligned','Ready')) else MUTED)
            sample=any(r.get('source')=='sample' for r in self.measurements.values())
            prefix='SAMPLE | ' if sample else ''
            banner.config(text=prefix+status['label']+' — '+status['detail'],fg=color)
        for name in ('X VIEW','Y VIEW'):
            widgets=self.engineering_widgets.get(name)
            if not widgets:continue
            canvas,label=widgets
            if not canvas.winfo_exists():continue
            result=self.measurements.get(name,{'valid':False,'reason':'Waiting for analysis...'})
            image=self.measurement_sources.get(name)
            stale=result.get('source')=='live' and time.monotonic()-(result.get('source_stamp') or 0)>2
            if image is not None:
                render_key=(id(image),result.get('measured_at'),stale,canvas.winfo_width(),canvas.winfo_height(),self.mask_views.get(name,False))
                if getattr(canvas,'render_key',None)!=render_key:
                    canvas.render_key=render_key
                    mask=self.analysis_masks.get(name)
                    shown=mask.copy() if self.mask_views.get(name) and mask is not None and not stale else self.overlay(image,result if not stale else {'valid':False})
                    shown.thumbnail((max(1,canvas.winfo_width()),max(1,canvas.winfo_height())),Image.Resampling.BILINEAR)
                    canvas.photo=ImageTk.PhotoImage(shown,master=self)
                    canvas.delete('all');canvas.create_image(canvas.winfo_width()/2,canvas.winfo_height()/2,image=canvas.photo)
            else:
                canvas.delete('all');canvas.create_text(100,60,text='No image',fill='white')
            origin='SAMPLE' if result.get('source')=='sample' else ('STALE' if stale else ('LIVE' if result.get('source')=='live' else 'UNAVAILABLE'))
            if result.get('valid') and not stale:
                cal=result.get('calibration_at_measurement')
                s=cal['um_per_px'] if cal else 1
                unit='µm' if cal else 'px (uncalibrated)'
                if result.get('detector')=='Notebook':
                    text=(f"{origin} | Notebook: 2 components\n"
                          f"Gap ≈ {result['gap_px']*s:.2f} {unit}\n"
                          f"Offset ≈ {result['offset_px']*s:+.2f} {unit} (right minus left)\n"
                          'Morphology shifts boundaries; accuracy not validated.')
                else:
                    text=(f"{origin} | Quality {result['quality']}/100 (heuristic)\n"
                          f"Gap ≈ {result['gap_px']*s:.2f} {unit}\n"
                          f"Offset ≈ {result['offset_px']*s:+.2f} {unit} | Angle ≈ {result['angle_deg']:+.2f}°\n"
                          f"Gap sampling uncertainty ≳ {4*s:.2f} {unit}")
                    for side in ('left','right'):
                        cleave=result.get('cleaves',{}).get(side,{})
                        if cleave.get('valid'):
                            text+=(f"\n{side.title()} cleave: {cleave['angle_error_deg']:+.1f}° | "
                                   f"RMS {cleave['rms_px']*s:.2f}, max {cleave['max_deviation_px']*s:.2f} {'µm' if cal else 'px'}")
                        else:text+=f"\n{side.title()} cleave: unresolved"
                    text+='\nSampled edge only • blue: ideal / white: fitted'
            else:text=f"{origin} | Measurement unavailable\n"+('Measurement expired; inspect capture age / processing time below.' if stale else result.get('reason',''))
            age=time.monotonic()-(result.get('source_stamp') or 0) if result.get('source')=='live' else None
            timing=f"Analysis {result.get('processing_ms',0):.0f} ms"
            if age is not None:timing+=f" | frame age {age:.2f} s"
            text=status['views'][name]+' | '+text+'\n'+timing
            label.full_measurement_text=text
            label.config(text='\n'.join(text.splitlines()[:3]))

